// Generates the simplified Europe silhouette used by the hero visual.
//
// Source: Natural Earth 1:50m admin-0 countries, packaged by `world-atlas`
// (public domain, https://www.naturalearthdata.com/about/terms-of-use/).
// Run with `node scripts/generate-europe-map.mjs` after `npm install`.
// The generated file is committed so production builds stay offline.

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { geoConicConformal, geoPath } from 'd3-geo';
import { merge } from 'topojson-client';
import { presimplify, simplify } from 'topojson-simplify';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');

const WIDTH = 540;
const HEIGHT = 480;
const PADDING = 26;

// Simplify enough to keep the inline path small while preserving coastlines.
const SIMPLIFY_WEIGHT = 0.02;

// Drop islands whose bounding box is smaller than this, in degrees. Keeps the
// silhouette legible at hero size without turning it into confetti.
const MIN_ISLAND_SPAN = 1;

const EUROPE = new Set([
	'Albania',
	'Austria',
	'Belarus',
	'Belgium',
	'Bosnia and Herz.',
	'Bulgaria',
	'Croatia',
	'Cyprus',
	'Czechia',
	'Denmark',
	'Estonia',
	'Finland',
	'France',
	'Germany',
	'Greece',
	'Hungary',
	'Iceland',
	'Ireland',
	'Italy',
	'Kosovo',
	'Latvia',
	'Lithuania',
	'Luxembourg',
	'Macedonia',
	'Moldova',
	'Montenegro',
	'Netherlands',
	'Norway',
	'Poland',
	'Portugal',
	'Romania',
	'Serbia',
	'Slovakia',
	'Slovenia',
	'Spain',
	'Sweden',
	'Switzerland',
	'Ukraine',
	'United Kingdom',
	// Drawn in addition to the core countries and included in the fit so no
	// landmass is clipped at the frame edge.
	'Turkey',
]);

const topology = simplify(
	presimplify(
		JSON.parse(
			await readFile(join(root, 'node_modules/world-atlas/countries-50m.json'), 'utf8'),
		),
	),
	SIMPLIFY_WEIGHT,
);

const geometries = topology.objects.countries.geometries;
const merged = merge(
	topology,
	geometries.filter((geometry) => EUROPE.has(geometry.properties.name)),
);

// Natural Earth bundles overseas territories with their parent country
// (French Guiana with France, Svalbard with Norway). Keep only polygons
// centred on the European window so the projection fits the continent.
const WINDOW = { lon: [-25, 45], lat: [34, 72] };

const isEuropeanPolygon = (polygon) => {
	const ring = polygon[0];
	let minLon = Infinity;
	let maxLon = -Infinity;
	let minLat = Infinity;
	let maxLat = -Infinity;
	for (const [lon, lat] of ring) {
		minLon = Math.min(minLon, lon);
		maxLon = Math.max(maxLon, lon);
		minLat = Math.min(minLat, lat);
		maxLat = Math.max(maxLat, lat);
	}

	const centreLon = (minLon + maxLon) / 2;
	const centreLat = (minLat + maxLat) / 2;
	const inWindow =
		centreLon >= WINDOW.lon[0] &&
		centreLon <= WINDOW.lon[1] &&
		centreLat >= WINDOW.lat[0] &&
		centreLat <= WINDOW.lat[1];

	return inWindow && maxLon - minLon + (maxLat - minLat) >= MIN_ISLAND_SPAN;
};

const geometry = {
	...merged,
	coordinates: merged.coordinates.filter(isEuropeanPolygon),
};

const projection = geoConicConformal()
	.parallels([43, 62])
	.rotate([-12, 0])
	.fitExtent(
		[
			[PADDING, PADDING],
			[WIDTH - PADDING, HEIGHT - PADDING],
		],
		geometry,
	)
	.clipExtent([
		[0, 0],
		[WIDTH, HEIGHT],
	]);

const path = geoPath(projection).digits(1);
const landPath = path(geometry);

if (!landPath) {
	throw new Error('Projection produced an empty path.');
}

const output = `// Generated by scripts/generate-europe-map.mjs — do not edit by hand.
// Geometry: Natural Earth 1:50m admin-0 countries via world-atlas (public domain).

export const europeMap = {
	viewBox: '0 0 ${WIDTH} ${HEIGHT}',
	landPath:
		${JSON.stringify(landPath)},
} as const;
`;

const target = join(root, 'src/data/europe.ts');
await mkdir(dirname(target), { recursive: true });
await writeFile(target, output, 'utf8');

console.log(`Wrote ${target}`);
console.log(`Path length: ${landPath.length.toLocaleString()} chars`);
